mapper.select:
select  a.id,a.name,a.priority,a.owner,a.status,a.create_man,a.create_man_id,a.create_date,a.modify_date,
c.name productLineName ,d.name bizDomainName
from product_demand a
left join project_product_demand b on a.id=b.product_demand_id and b.is_deleted =false
left join product_line c on a.product_line_id=c.id and c.is_deleted =false
left join biz_domain d on c.biz_domain_id=d.id and d.is_deleted =false

    and a.id = #{id}
    and a.name like concat('%',#{name},'%')

        and a.create_date >= #{createDateStart} and a.create_date <= #{createDateEnd}


        and a.modify_date >= #{modifyDateStart} and a.modify_date <= #{modifyDateEnd}


        and c.id in

            #{item}



        and d.id in

            #{item}



        and a.owner_id in

            #{item}



        and a.create_man_id in

            #{item}



        and a.status in

            #{item}


    and b.project_id  is null and  a.is_deleted =false
